import{_ as a,o as t,c as r,ap as i,by as s,bz as o,bA as d,bB as n,bC as m,bD as c}from"./chunks/framework.BumGKp4W.js";const b=JSON.parse('{"title":"Firmware Update","description":"","frontmatter":{"permalink":"/docs/usage/resource-management/firmware-update"},"headers":[],"relativePath":"docs/usage/resource-management/firmware-update.md","filePath":"docs/usage/resource-management/firmware-update.md"}'),l={name:"docs/usage/resource-management/firmware-update.md"};function p(u,e,h,f,w,v){return t(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="firmware-update" tabindex="-1">Firmware Update <a class="header-anchor" href="#firmware-update" aria-label="Permalink to “Firmware Update”">​</a></h1><h2 id="concept" tabindex="-1">Concept <a class="header-anchor" href="#concept" aria-label="Permalink to “Concept”">​</a></h2><p>Firmware updates are executed, as well as the <a href="/slm/docs/usage/resource-management/discovery.html">discovery of devices</a>, by drivers. Based on the device information collected during discovery, SLM retrieves firmware update metadata from the manufacturers&#39; AAS servers and evaluates it. For this evaluation, submodels based on the IDTA templates <strong>Product Change Notification</strong> and <strong>Software Nameplate</strong> are used. <img src="'+s+'" alt="Submodel overview of a device" data-zoomable="true"></p><h2 id="firmware-update-files" tabindex="-1">Firmware update files <a class="header-anchor" href="#firmware-update-files" aria-label="Permalink to “Firmware update files”">​</a></h2><p>Firmware update files are manged per device type. This means that all devices of a specific type share the same firmware update versions and files. This is based on the assumption that devices of the same type have the same hardware and thus can be updated with the same firmware. To manage the device types go to the device type overview and select the device type to manage. <img src="'+o+'" alt="Overview of device types" data-zoomable="true"></p><p>For each device type, available firmware updates can be provided in two ways:</p><ul><li><strong>Direct download</strong> via a configured URL by pressing the download button beside the installation URI. This will trigger the download of the firmware file from the manufacturer&#39;s server and store it in SLM. THe installation URI must be publicly accessible.</li><li><strong>Manual upload</strong> of firmware files</li></ul><p><img src="'+d+'" alt="Firmware management in the device type view" data-zoomable="true"></p><h2 id="execute-firmware-update" tabindex="-1">Execute firmware update <a class="header-anchor" href="#execute-firmware-update" aria-label="Permalink to “Execute firmware update”">​</a></h2><p>In the details view of a device instance, available firmware versions can be inspected and an update can be triggered directly. <img src="'+n+'" alt="Overview in the firmware tab of a device instance" data-zoomable="true"></p><p>If the firmware update process on the target device requires credentials, they must be created first or existing credentials must be linked to the device. The conceptual description of the credential management is available in the <a href="/slm/docs/usage/common/credential-management.html">Credential Management section</a>. <img src="'+m+'" alt="Firmware update activation with job status" data-zoomable="true"></p><p>During the update process, the job status is shown including individual steps and driver log output. After successful completion, the new firmware version is marked as installed and the firmware version is updated. <img src="'+c+'" alt="Completed firmware update in the device instance view" data-zoomable="true"></p>',12)])])}const _=a(l,[["render",p]]);export{b as __pageData,_ as default};
